interface IValidator {
  validate(value: string): boolean;
}

interface ISanitizer {
  sanitize(value: string): string;
}

class EmailValidator implements IValidator {
  private readonly emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  validate(email: string): boolean {
    return this.emailRegex.test(email);
  }
}

class HtmlSanitizer implements ISanitizer {
  private readonly replacements: ReadonlyArray<[RegExp, string]> = [
    [/</g, '&lt;'], [/>/g, '&gt;'], [/"/g, '&quot;'], [/'/g, '&#039;']
  ];
  sanitize(input: string): string {
    return this.replacements.reduce(
      (acc, [pattern, replacement]) => acc.replace(pattern, replacement),
      input
    );
  }
}

class ValidationService {
  constructor(
    private readonly emailValidator: IValidator,
    private readonly htmlSanitizer: ISanitizer
  ) {}

  validateEmail(email: string): void {
    if (!email || !this.emailValidator.validate(email)) {
      throw new Error('Invalid email format');
    }
  }

  sanitizeName(name: string): string {
    if (!name) throw new Error('Name is required');
    return this.htmlSanitizer.sanitize(name);
  }
}

