class EmailAddress {
  private constructor(private readonly value: string) {}

  static create(email: string): Result<EmailAddress, ValidationError> {
    const trimmed = email.trim().toLowerCase();
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(trimmed)) {
      return { success: false, error: new ValidationError('Invalid email format', 'email') };
    }
    return { success: true, value: new EmailAddress(trimmed) };
  }

  toString(): string { return this.value; }
  equals(other: EmailAddress): boolean { return this.value === other.value; }
}

class UserName {
  private constructor(private readonly value: string) {}

  static create(name: string): Result<UserName, ValidationError> {
    const trimmed = name.trim();
    if (trimmed.length === 0 || trimmed.length > 255) {
      return { success: false, error: new ValidationError('Invalid name', 'name') };
    }
    const sanitized = trimmed.replace(/</g, '&lt;').replace(/>/g, '&gt;');
    return { success: true, value: new UserName(sanitized) };
  }

  toString(): string { return this.value; }
}

